<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';
 if($action==='featured'){$pdo->prepare('UPDATE twibbons SET is_featured=1-is_featured WHERE id=?')->execute([$id]);flash('success','Status karya pilihan diperbarui.');}
 elseif($action==='approve'){$pdo->prepare("UPDATE twibbons SET moderation_status='approved',visibility='public' WHERE id=?")->execute([$id]);flash('success','Karya disetujui dan ditampilkan ke publik.');}
 elseif($action==='unpublish'){$pdo->prepare("UPDATE twibbons SET visibility='unlisted',is_featured=0 WHERE id=?")->execute([$id]);flash('success','Karya disembunyikan dari Jelajahi.');}
 elseif($action==='delete'){$stmt=$pdo->prepare('SELECT template_image FROM twibbons WHERE id=?');$stmt->execute([$id]);if($item=$stmt->fetch()){$pdo->prepare('DELETE FROM twibbons WHERE id=?')->execute([$id]);$path=__DIR__.'/uploads/'.basename($item['template_image']);if(is_file($path)&&basename($path)!=='sample_template.png')@unlink($path);flash('success','Karya berhasil dihapus.');}}
 redirect('admin');
}
$requestedFilter=(string)($_GET['filter']??'all');$filter=in_array($requestedFilter,['all','public','pending','unlisted','private'],true)?$requestedFilter:'all';$conditions=['all'=>'1=1','public'=>"t.visibility='public'",'pending'=>"t.moderation_status='pending'",'unlisted'=>"t.visibility='unlisted'",'private'=>"t.visibility='private'"];$where=$conditions[$filter];try{$items=$pdo->query("SELECT t.*,u.name author_name,u.email author_email,c.name category_name FROM twibbons t LEFT JOIN users u ON u.id=t.owner_id LEFT JOIN categories c ON c.id=t.category_id WHERE {$where} ORDER BY t.created_at DESC")->fetchAll();}catch(PDOException $e){error_log('Admin artworks error: '.$e->getMessage());$items=[];flash('error','Daftar karya belum dapat dimuat. Coba muat ulang halaman.');}$flash=pull_flash();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Karya — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Administrator</span><h1 class="page-title" style="margin-top:12px">Kelola karya</h1><p class="subtitle">Kurasi seluruh karya kreator tanpa membuat jalur unggah terpisah.</p></div><a class="btn btn-primary" href="karya-baru">＋ Buat karya</a></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="admin-filter-tabs"><?php foreach(['all'=>'Semua','public'=>'Publik','pending'=>'Menunggu','unlisted'=>'Via tautan','private'=>'Pribadi'] as $key=>$label):?><a class="<?=$filter===$key?'active':''?>" href="admin?filter=<?=$key?>"><?=$label?></a><?php endforeach?></div><div class="admin-work-list"><?php foreach($items as $item):?><article class="admin-work-row"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div class="admin-work-info"><div class="template-meta"><span class="visibility visibility-<?=$item['visibility']==='private'?'private':($item['visibility']==='public'?'public':'unlisted')?>"><?=e($item['visibility'])?></span><span class="moderation-status status-<?=e($item['moderation_status'])?>"><?=e($item['moderation_status'])?></span><?php if($item['is_featured']):?><span class="featured-inline">Pilihan editor</span><?php endif?></div><h2><?=e($item['title'])?></h2><p><?=e($item['category_name']?:'Tanpa kategori')?> · oleh <?=e($item['author_name']?:'Data lama')?> · <?=e(time_ago($item['created_at']))?></p></div><div class="admin-work-actions"><a class="btn btn-secondary btn-sm" href="admin/template/<?=(int)$item['id']?>/edit">Edit</a><a class="btn btn-secondary btn-sm" href="t/<?=e($item['slug'])?>">Buka</a><?php if($item['moderation_status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-primary btn-sm">Setujui</button></form><?php endif?><?php if($item['visibility']==='public'&&$item['moderation_status']==='approved'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="featured"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-secondary btn-sm"><?=$item['is_featured']?'Batalkan pilihan':'Jadikan pilihan'?></button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unpublish"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-secondary btn-sm">Sembunyikan</button></form><?php endif?><form method="post" data-confirm="Hapus karya ini secara permanen?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div></article><?php endforeach?></div><?php if(!$items):?><div class="empty">Tidak ada karya pada filter ini.</div><?php endif?></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
